def uid(f,anchor):return 'content/chapters/'+f+'::'+anchor
def owner(f,line):
    candidates=[(k,u) for k,u in P['units'].items() if k.startswith('content/chapters/'+f+'::')]
    exact=[k for k,u in candidates if any(p['line']<=line<=p['end_line'] for p in u['paragraphs'])]
    if exact:return exact[0]
    headings=[(n+1,s.split('{#')[1].split('}')[0]) for n,s in enumerate(lines[f]) if '{#' in s and s.startswith('#')]
    return uid(f,max((x for x in headings if x[0]<=line),default=headings[0])[1])
def edit(f,line,changes,reason):
    key=(f,line)
    if key in line_edits:
        e=line_edits[key];text=e['replacement'];e['reason']+=' '+reason
    else:
        text=lines[f][line-1];e={'id':f'PLACE-L{len(E)+1:03d}','source':'content/chapters/'+f,'line':line,'original':text,'replacement':None,'reason':reason,'unit_ids':[owner(f,line)],'status':'proposed'};E.append(e);line_edits[key]=e
    for old,new in changes:
        assert old in text,(f,line,old)
        text=text.replace(old,new,1)
    e['replacement']=text
    return e['id']
